"""Independent reference implementations written straight from the spec.
Deliberately slow/naive; used only for differential testing."""
from math import gcd

PS = 10**6
NS = 10**9
INF = float('inf')

def ref_calibration(profile):
    K = profile['groups']
    edges = []
    for i, (a, b, L, U) in enumerate(profile['measurements']):
        edges.append((a, b, U, 2 * i))
        edges.append((b, a, -L, 2 * i + 1))
    dist = [0] * K
    bad = False
    for it in range(K + 1):
        upd = False
        for a, b, w, i in edges:
            if dist[a] + w < dist[b]:
                dist[b] = dist[a] + w
                upd = True
        if not upd:
            break
        if it == K:
            bad = True
    if bad:
        return ('bad',)
    D = [[0] * K for _ in range(K)]
    for s in range(K):
        d = [INF] * K
        d[s] = 0
        for _ in range(K - 1):
            for a, b, w, i in edges:
                if d[a] != INF and d[a] + w < d[b]:
                    d[b] = d[a] + w
        D[s] = [int(x) for x in d]
    jit = profile['jitter_ps']
    H = [[0] * K for _ in range(K)]
    C = [[0] * K for _ in range(K)]
    for a in range(K):
        for b in range(K):
            hi = D[a][b]; lo = -D[b][a]
            H[a][b] = (hi - lo) * PS // 2 + (jit[a] + jit[b]) * PS
            C[a][b] = (hi + lo) * PS // 2
    return ('ok', D, H, C)

def ref_setup(fabric):
    N = fabric['n']; T = fabric['interval_ns']; S = fabric['slice_ns']
    O = fabric['offset_ns']
    Q = len(fabric['slices'])
    mod = Q * S
    P = mod // gcd(T, mod)
    fsl = [((O + p * T) // S) % Q for p in range(P)]
    fro = [(O + p * T) % S for p in range(P)]
    V = [[fabric['drift_ppb'][i]] * P for i in range(N)]
    for (nd, st, en, ex) in fabric['heat']:
        for p in range(st, en):
            V[nd][p] += ex
    VR = [[V[i][p] * T for p in range(P)] for i in range(N)]  # as/interval
    return P, N, T, S, fsl, fro, VR

def ref_dir(fabric, code):
    l = code // 2
    dr = code % 2
    lk = fabric['links'][l]
    frm = lk['ends'][dr]
    to = lk['ends'][1 - dr]
    d = lk['delay_ns'][dr]
    q = lk['defer_rounds'][dr]
    T = fabric['interval_ns']
    m = -(-d // T)
    return l, frm, to, d, q, m, m + q

def ref_hop_ok(fabric, P, fsl, fro, code, p, g):
    S = fabric['slice_ns']
    l, frm, to, d, q, m, L = ref_dir(fabric, code)
    if l not in fabric['slices'][fsl[p]]:
        return False
    for (bl, bst, ben) in fabric['blackouts']:
        if bl != l:
            continue
        for x in range(p, p + m):
            if bst <= (x % P) < ben:
                return False
    rho = fro[p]
    if rho < g or rho + d + g > S:
        return False
    return True

def ref_aging(VR, wn, p, d, m, q, P, T):
    vh = VR[wn]
    tot = (m * T - d) * vh[(p + d // T) % P]
    for j in range(p + m, p + m + q):
        tot += vh[j % P]
    return tot

def ref_plan(profile, fabric):
    cal = ref_calibration(profile)
    if cal[0] == 'bad':
        return {'status': 'inconsistent'}
    _, D, H, C = cal
    P, N, T, S, fsl, fro, VR = ref_setup(fabric)
    anchors = fabric['anchors']
    guards = fabric['guards_ns']
    rc = fabric['reconfig_ns']

    def anchored(i, p):
        return any(a == i and st <= p < en for (a, st, en) in anchors)

    # all directed hops by departure phase
    hops_at = [[] for _ in range(P)]
    for p in range(P):
        for lid in fabric['slices'][fsl[p]]:
            for dr in (0, 1):
                code = 2 * lid + dr
                l, frm, to, d, q, m, L = ref_dir(fabric, code)
                gmax = min(fro[p], S - d - fro[p])
                cost = H[frm[2]][to[2]] + ref_aging(VR, to[0], p, d, m, q, P, T)
                hops_at[p].append((code, frm[0], to[0], L, cost, gmax, m))

    def envelope_for(g):
        Vn = P * N
        Tmax = 16 * Vn + 2 * P + 4
        E = [[None] * N for _ in range(Tmax + 1)]
        for t in range(Tmax + 1):
            p = t % P
            for i in range(N):
                if anchored(i, p):
                    E[t][i] = (0, 0)
            if t > 0:
                for i in range(N):
                    if E[t - 1][i] is not None:
                        e, a = E[t - 1][i]
                        cand = (e + VR[i][(t - 1) % P], a + 1)
                        cur = E[t][i]
                        if cur is None or cand < cur:
                            E[t][i] = cand
                for p2 in range(P):
                    for (code, fn, wn, L, cost, gmax, m) in hops_at[p2]:
                        if gmax < g:
                            continue
                        if (t - L) % P != p2 or t < L:
                            continue
                        src = E[t - L][fn]
                        if src is not None:
                            cand = (src[0] + cost, src[1] + L)
                            cur = E[t][wn]
                            if cur is None or cand < cur:
                                E[t][wn] = cand
        B = [[None] * N for _ in range(P)]
        A = [[None] * N for _ in range(P)]
        for p in range(P):
            for i in range(N):
                best = None
                for t in range(p, Tmax + 1, P):
                    v = E[t][i]
                    if v is not None and (best is None or v < best):
                        best = v
                if best is not None:
                    B[p][i] = best[0]
                    A[p][i] = best[1]
        return B, A, E, Tmax

    peaks = []
    sel = None
    data = {}
    for g in guards:
        B, A, E, Tmax = envelope_for(g)
        data[g] = (B, A, E, Tmax)
        pk = 0
        okall = True
        for p in range(P):
            for i in range(N):
                if B[p][i] is None:
                    okall = False
                    break
                val = B[p][i] + VR[i][p]
                if val > pk:
                    pk = val
            if not okall:
                break
        peaks.append(pk if okall else None)
        if sel is None and okall and pk + rc * NS <= g * NS:
            sel = g
    out = {'P': P, 'peaks': peaks, 'guard': sel}
    if sel is None:
        return out
    B, A, E, Tmax = data[sel]
    warm = None
    for k in range(0, (Tmax - P) // P + 1):
        good = True
        for p in range(P):
            t = k * P + p
            for i in range(N):
                if E[t][i] is None or E[t][i][0] != B[p][i]:
                    good = False
                    break
            if not good:
                break
        if good:
            warm = k
            break
        # if E already below B somewhere: impossible; but check horizon
    out['bounds'] = B
    out['ages'] = A
    out['warmup'] = warm
    return out

def ref_replay(profile, fabric, guard, trace):
    cal = ref_calibration(profile)
    if cal[0] == 'bad':
        return {'status': 'inconsistent'}
    _, D, H, C = cal
    P, N, T, S, fsl, fro, VR = ref_setup(fabric)
    R = trace['rounds']
    rates = trace['rates_ppb']
    bias = trace['bias_ps']
    lost = set(trace['lost'])
    anchors = fabric['anchors']
    g = guard
    err = [None] * N
    bnd = [None] * N
    gen = [0] * N
    pend = []
    status = {}
    delivered = adopted = unknowns = stale = pending = 0
    peak = 0
    always_known = True
    states = {}
    adopt_at = {}

    for t in range(R + 1):
        p = t % P
        if t > 0:
            for i in range(N):
                if bnd[i] is not None:
                    err[i] = err[i] + rates[t - 1][i] * T
                    bnd[i] = bnd[i] + VR[i][(t - 1) % P]
                    peak = max(peak, abs(err[i]))
        for (rt, rn) in trace['reboots']:
            if rt == t:
                gen[rn] += 1
                err[rn] = None
                bnd[rn] = None
        for (an, ast, aen) in anchors:
            if ast <= p < aen:
                err[an] = 0
                bnd[an] = 0
        due = [x for x in pend if x[0] == t]
        pend = [x for x in pend if x[0] != t]
        for i in range(N):
            pk = [x for x in due if x[3] == i]
            if not pk:
                continue
            delivered += len(pk)
            remain = []
            for x in pk:
                if x[6] != gen[x[2]] or x[7] != gen[i]:
                    stale += 1
                    continue
                if x[4] is None:
                    unknowns += 1
                    continue
                remain.append(x)
            if remain:
                best = min(remain, key=lambda x: (x[5], x[1]))
                held = bnd[i]
                if held is None or best[5] < held:
                    err[i] = best[4]
                    bnd[i] = best[5]
                    adopted += 1
                    adopt_at.setdefault(t, {})[i] = best[1]
                    peak = max(peak, abs(best[4]))
        if any(b is None for b in bnd):
            always_known = False
        if t in trace['queries']:
            states[t] = {"bounds_as": bnd[:], "errors_as": err[:],
                         "adopted": [adopt_at.get(t, {}).get(i) for i in range(N)],
                         "generations": gen[:]}
        sd = sorted([x for x in trace['sends'] if x[1] == t], key=lambda x: x[0])
        used = set()
        for (sid, tick, code, jit) in sd:
            l, frm, to, d, q, m, L = ref_dir(fabric, code)
            if l not in fabric['slices'][fsl[p]]:
                status[sid] = 'not_in_slice'
                continue
            bl = False
            for (bl2, bst, ben) in fabric['blackouts']:
                if bl2 != l:
                    continue
                for x in range(t, t + m):
                    if bst <= (x % P) < ben:
                        bl = True
            if bl:
                status[sid] = 'blackout'
                continue
            if fro[p] < g or fro[p] + d + g > S:
                status[sid] = 'guard'
                continue
            key = (frm[0], frm[1])
            if key in used:
                status[sid] = 'port_busy'
                continue
            used.add(key)
            if sid in lost:
                status[sid] = 'lost'
                continue
            status[sid] = 'sent'
            pa = t + L
            srcn = frm[0]
            dstn = to[0]
            if err[srcn] is None:
                ce = None
                cb = None
            else:
                ce = err[srcn] + (bias[to[2]] - bias[frm[2]]) * PS + jit - C[frm[2]][to[2]]
                cb = bnd[srcn] + H[frm[2]][to[2]] + ref_aging(VR, dstn, t, d, m, q, P, T)
                if (m * T - d) > 0:
                    ce += rates[t + d // T][dstn] * (m * T - d)
                for j in range(t + m, pa):
                    ce += rates[j][dstn] * T
            if pa > R:
                pending += 1
                continue
            pend.append((pa, sid, srcn, dstn, ce, cb, gen[srcn], gen[dstn]))
    return {"status": "ok",
            "states": [states[q] for q in trace['queries']],
            "send_status": [status[x[0]] for x in trace['sends']],
            "delivered": delivered, "adopted": adopted,
            "unknown_payloads": unknowns, "stale_payloads": stale,
            "pending": pending, "peak_known_abs_as": peak,
            "always_known": always_known}
